**顺序表（Sequential List）**是采用顺序存储结构的线性表，即用一组地址连续的存储单元依次存储线性表的数据元素。

**C++中的实现：**
```cpp
#define MAXSIZE 100
typedef struct {
    int data[MAXSIZE];  // 存储空间
    int length;         // 当前长度
} SqList;
```

**特点：**
- ✅ 优点：随机访问，查找第i个元素 O(1)；存储密度高
- ❌ 缺点：插入删除需要移动大量元素 O(n)；存储空间需预分配

**基本操作：**
```cpp
// 初始化
void InitList(SqList &L) { L.length = 0; }

// 获取第i个元素 O(1)
bool GetElem(SqList L, int i, int &e) {
    if (i < 1 || i > L.length) return false;
    e = L.data[i-1];
    return true;
}

// 插入元素 O(n) - 平均移动 n/2 个元素
bool ListInsert(SqList &L, int i, int e) {
    if (L.length >= MAXSIZE || i < 1 || i > L.length+1) return false;
    for (int j = L.length; j >= i; j--)  // 第i个位置及之后后移
        L.data[j] = L.data[j-1];
    L.data[i-1] = e;
    L.length++;
    return true;
}

// 删除元素 O(n) - 平均移动 (n-1)/2 个元素
bool ListDelete(SqList &L, int i, int &e) {
    if (L.length == 0 || i < 1 || i > L.length) return false;
    e = L.data[i-1];
    for (int j = i; j < L.length; j++)  // 第i个位置之后前移
        L.data[j-1] = L.data[j];
    L.length--;
    return true;
}
```

**动态顺序表（可扩容）：**
使用动态数组实现，当空间不足时重新分配更大空间。
```cpp
typedef struct {
    int *data;     // 动态数组指针
    int length;    // 当前长度
    int capacity;  // 当前容量
} SqList;

void InitList(SqList &L) {
    L.data = new int[10];
    L.length = 0;
    L.capacity = 10;
}
```

**单链表（Single Linked List）**用一组任意的存储单元存储线性表的数据元素，每个元素包含数据域和指针域。

**结点结构：**
```cpp
typedef struct LNode {
    int data;           // 数据域
    struct LNode* next; // 指针域
} LNode, *LinkList;
```

**特点：**
- ✅ 优点：插入删除无需移动元素（找到位置后 O(1)）；按需分配
- ❌ 缺点：只能顺序访问，查找需要遍历 O(n)

**头结点 vs 首元结点：**
- **头结点**：链表第一个结点之前附设的结点，其指针域指向首元结点。设头结点的好处：空表和非空表操作统一；首元结点操作与其他结点统一。
- **首元结点**：链表中存储第一个数据元素的结点

**单链表操作：**
```cpp
// 头插法创建单链表 O(n)
void CreateList_H(LinkList &L, int n) {
    L = new LNode;         // 创建头结点
    L->next = NULL;
    for (int i = 0; i < n; i++) {
        LNode* p = new LNode;
        cin >> p->data;
        p->next = L->next;  // 新结点指向原首元
        L->next = p;         // 头结点指向新结点
    }
}

// 尾插法创建单链表 O(n)
void CreateList_R(LinkList &L, int n) {
    L = new LNode;
    L->next = NULL;
    LNode* r = L;           // r为表尾指针
    for (int i = 0; i < n; i++) {
        LNode* p = new LNode;
        cin >> p->data;
        p->next = NULL;
        r->next = p;        // 原表尾指向新结点
        r = p;              // r移到新表尾
    }
}

// 查找第i个元素 O(n)
LNode* GetElem(LinkList L, int i) {
    LNode* p = L->next;
    int j = 1;
    while (p && j < i) { p = p->next; j++; }
    return (j == i) ? p : NULL;
}

// 在第i个位置插入元素e O(n)查找 + O(1)插入
bool ListInsert(LinkList &L, int i, int e) {
    LNode* p = L; int j = 0;
    while (p && j < i-1) { p = p->next; j++; }  // 找到第i-1个结点
    if (!p || j > i-1) return false;
    LNode* s = new LNode;
    s->data = e;
    s->next = p->next;  // 新结点指向原第i个结点
    p->next = s;        // 第i-1个结点指向新结点
    return true;
}

// 删除第i个元素 O(n)查找 + O(1)删除
bool ListDelete(LinkList &L, int i, int &e) {
    LNode* p = L; int j = 0;
    while (p->next && j < i-1) { p = p->next; j++; }
    if (!p->next || j > i-1) return false;
    LNode* q = p->next;
    e = q->data;
    p->next = q->next;
    delete q;
    return true;
}
```

**应用一：两个有序表的合并**

问题：将两个有序表 La（递增）和 Lb（递增）合并为一个新的有序表 Lc。

```cpp
// 时间复杂度 O(m+n)，空间复杂度 O(m+n)
void MergeList(SqList La, SqList Lb, SqList &Lc) {
    Lc.length = La.length + Lb.length;
    int i = 0, j = 0, k = 0;  // i,j分别遍历La,Lb， k记录Lc位置
    while (i < La.length && j < Lb.length) {
        if (La.data[i] <= Lb.data[j]) Lc.data[k++] = La.data[i++];
        else Lc.data[k++] = Lb.data[j++];
    }
    while (i < La.length) Lc.data[k++] = La.data[i++];  // 复制剩余
    while (j < Lb.length) Lc.data[k++] = Lb.data[j++];
}
```

**应用二：一元多项式的表示与相加**

用线性表表示多项式：P(x) = a0 + a1*x + a2*x^2 + ... + an*x^n

方法一：用数组（指数作下标，值为系数）——适合项数多且连续的多项式
方法二：用链表（每项存储系数和指数）——适合稀疏多项式

```cpp
// 多项式链表结点
typedef struct PNode {
    int coef;      // 系数
    int expn;      // 指数
    struct PNode* next;
} PNode, *Polynomial;

// 多项式相加：A(x) + B(x)，结果存于A
void AddPolyn(Polynomial &Pa, Polynomial &Pb) {
    PNode *p1 = Pa->next, *p2 = Pb->next;
    PNode *p = Pa;  // p始终指向p1的前驱
    while (p1 && p2) {
        if (p1->expn == p2->expn) {  // 指数相同，系数相加
            p1->coef += p2->coef;
            if (p1->coef == 0) {      // 系数为0，删除p1
                p->next = p1->next;
                delete p1; p1 = p->next;
            } else { p = p1; p1 = p1->next; }
            PNode* q = p2; p2 = p2->next; delete q;
        } else if (p1->expn < p2->expn) {  // p1指数小，保留
            p = p1; p1 = p1->next;
        } else {  // p2指数小，插入p2到p1之前
            PNode* q = p2->next;  // 保存p2的后继
            p2->next = p1; p->next = p2;  // p2插入p之后
            p = p2; p2 = q;
        }
    }
    if (p2) p->next = p2;  // 链接Pb的剩余项
    delete Pb;  // 释放Pb的头结点
}
```

**应用三：约瑟夫环问题**

问题：n个人围成一圈，从第1个人开始报数，数到m的人出列，接着从下一个人开始重新报数，数到m的人出列...直到所有人出列。

解法：用循环链表模拟，每次删除第m个结点。

code_examples.code:
#include <iostream>
using namespace std;

typedef struct LNode {
    int data;
    struct LNode* next;
} LNode, *LinkList;

// 尾插法创建单链表 O(n)
void CreateList_R(LinkList &L, int n) {
    L = new LNode; L->next = NULL;
    LNode* r = L;  // r为表尾指针
    for (int i = 0; i < n; i++) {
        LNode* p = new LNode;
        cin >> p->data;
        p->next = NULL;
        r->next = p; r = p;
    }
}

// 遍历输出链表
void PrintList(LinkList L) {
    LNode* p = L->next;
    while (p) {
        cout << p->data << " ";
        p = p->next;
    }
    cout << endl;
}

// 链表反转【经典题目】O(n)，空间O(1)
LinkList ReverseList(LinkList L) {
    LNode* prev = NULL;
    LNode* curr = L->next;
    while (curr) {
        LNode* next = curr->next;  // 保存下一节点
        curr->next = prev;          // 当前节点指向前驱
        prev = curr;                // prev前移
        curr = next;                // curr前移
    }
    L->next = prev;  // 头结点指向新首元
    return L;
}

// 合并两个有序链表【经典题目】O(m+n)
LinkList MergeList(LinkList La, LinkList Lb) {
    LinkList Lc = new LNode;
    LNode* pa = La->next, *pb = Lb->next, *pc = Lc;
    while (pa && pb) {
        if (pa->data <= pb->data) {
            pc->next = pa; pc = pa; pa = pa->next;
        } else {
            pc->next = pb; pc = pb; pb = pb->next;
        }
    }
    pc->next = pa ? pa : pb;  // 链接剩余部分
    return Lc;
}

// 判断链表是否有环（快慢指针法）O(n)
bool hasCycle(LinkList L) {
    LNode *slow = L->next, *fast = L->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

// 找链表中间结点（快慢指针法）
LNode* findMiddle(LinkList L) {
    LNode *slow = L->next, *fast = L->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;  // 对于奇数个结点，返回正中间
}

// 删除链表倒数第n个结点 O(n)
LinkList removeNthFromEnd(LinkList L, int n) {
    LNode *fast = L, *slow = L;
    for (int i = 0; i < n; i++) fast = fast->next;  // fast先走n步
    while (fast->next) {  // 同时走，fast到末尾时slow在倒数第n+1
        fast = fast->next; slow = slow->next;
    }
    LNode* temp = slow->next;
    slow->next = slow->next->next;
    delete temp;
    return L;
}

// 多项式 P(x) = 3x^14 + 2x^8 + 5x^3 + 1
// 用链表存储，每项包含(coef, expn)

#include <iostream>
using namespace std;

typedef struct PNode {
    int coef;      // 系数
    int expn;      // 指数
    struct PNode* next;
} PNode, *Polynomial;

// 创建多项式：输入n个(系数,指数)对，按指数降序排列
void CreatePolyn(Polynomial &P, int n) {
    P = new PNode; P->next = NULL;
    PNode* r = P;
    cout << "请输入n个(系数,指数)对（按指数降序）：" << endl;
    for (int i = 0; i < n; i++) {
        PNode* s = new PNode;
        cin >> s->coef >> s->expn;
        s->next = NULL;
        r->next = s; r = s;
    }
}

// 输出多项式
void PrintPolyn(Polynomial P) {
    PNode* p = P->next;
    bool first = true;
    while (p) {
        if (p->coef > 0 && !first) cout << "+";
        if (p->expn == 0) cout << p->coef;
        else if (p->expn == 1) cout << p->coef << "x";
        else cout << p->coef << "x^" << p->expn;
        p = p->next; first = false;
    }
    cout << endl;
}

// 多项式相加：Pa = Pa + Pb
void AddPolyn(Polynomial &Pa, Polynomial &Pb) {
    PNode *p1 = Pa->next, *p2 = Pb->next;
    PNode *p = Pa;  // p始终指向p1的前驱
    while (p1 && p2) {
        if (p1->expn == p2->expn) {  // 指数相同
            p1->coef += p2->coef;
            if (p1->coef == 0) {  // 系数为0
                p->next = p1->next; delete p1; p1 = p->next;
            } else { p = p1; p1 = p1->next; }
            PNode* q = p2; p2 = p2->next; delete q;
        } else if (p1->expn > p2->expn) {  // p1指数大，不动
            p = p1; p1 = p1->next;
        } else {  // p2指数大，插入到p1之前
            PNode* q = p2->next;
            p2->next = p1; p->next = p2;
            p = p2; p2 = q;
        }
    }
    if (p2) p->next = p2;
    delete Pb;
}

// 示例：
// Pa = 3x^14 + 2x^8 + 5x^3 + 1
// Pb = 8x^14 - 3x^10 + 10x^6 + 6x^3
// Pa + Pb = 11x^14 - 3x^10 + 2x^8 + 10x^6 + 11x^3 + 1

